sp_theme.css_variables:
// Grays
$gray-base: #000000;
$gray-dark: lighten($gray-base, 18.04%);
$gray-darker: lighten($gray-base, 8.24%);
$gray-light: lighten($gray-base, 40%);
$gray-lighter: lighten($gray-base, 94.51%);
$gray: lighten($gray-base, 29.02%);

////// Branding variables //////
// should always end with !default and no other variable should have !default
$brand-primary: #E30613 !default;
$body-bg: #ffffff !default;
$brand-success: #007A33 !default;
$state-success-text: darken(desaturate(adjust-hue($brand-success, 3), 15.64%), 34.31) !default;
$sp-navbar-divider-color: #0F5C36 !default;
$text-color: $gray-dark !default;
$navbar-inverse-link-hover-color: #FCD34D !default;
$navbar-inverse-bg: #00532B !default;
$brand-warning: #E8A200 !default;
$brand-danger: #B10510 !default;
$sp-tagline-color: #ffffff !default;
$navbar-inverse-link-active-color: $sp-tagline-color !default;
$navbar-inverse-link-color: #C9D8CE !default;
$brand-info: #3FA66B !default;
$link-color: #C81420 !default;
$sp-logo-margin-x: 15px !default;
$text-muted: $gray-light !default;
////////////////////////////////////

// Link hover decoration
$link-hover-decoration: underline !default;

// SPAR theme variables
$brand-primary-dark: darken($brand-primary, 20%);
$brand-primary-darker: #7A0308 !default;
$brand-primary-light: #F3949B !default;
$brand-primary-lighter: #FBC7CA !default;
$brand-primary-lightest: #FDF2F2 !default;
$dropdown-link-disabled-color: $gray-light;
$link-hover-color: darken(desaturate(adjust-hue($link-color, 1), 0.42%), 16.67);
$navbar-inverse-link-active-bg: #003D1F;
$navbar-inverse-link-hover-bg: #00713F;
$panel-primary-border: $brand-primary;
$panel-primary-heading-bg: $brand-primary;
$panel-primary-text: #ffffff;
$primary: $brand-primary;
$input-border-focus: #E30613;
$quicklinks-background: #FDF2F2;
$btn-success-bg: $brand-success;
$btn-default-color: #2e2e2e;
$btn-primary-color: #ffffff;
$btn-primary-bg: $brand-primary;
$btn-primary-border: darken($btn-primary-bg, 5%);
$btn-success-bg: $brand-success;
$btn-success-border: darken($btn-success-bg, 5%);
$btn-success-color: darken(desaturate(adjust-hue($brand-success, 3), 15.64%), 34.31);
$btn-disabled-opacity: 0.25;
$component-active-color: $gray;
$component-active-bg: #f5f5f5;
$state-danger-bg: lighten(saturate(adjust-hue($brand-danger, 354), 42.52%), 42.94);
$state-danger-border: #B10510;
$state-danger-text: #64100A;
$state-info-bg: lighten(desaturate($brand-info, 3.27%), 19.02);
$state-info-border: $brand-info;
$state-info-text: darken(desaturate(adjust-hue($brand-info, 1), 2.75%), 41.57);
$state-success-bg: lighten(saturate($brand-success, 3.67%), 28.24);
$state-success-border: $brand-success;
$state-warning-bg: lighten(saturate(adjust-hue($brand-warning, -3), 17.70%), 29.61);
$state-warning-border: $brand-warning;
$state-warning-text: darken(desaturate(adjust-hue($brand-warning, -4), 20.32%), 44.31);
$alert-danger-bg: $state-danger-bg;
$alert-danger-border: $state-danger-border;
$alert-danger-text: $state-danger-text;
$alert-info-bg: $state-info-bg;
$alert-info-border: $state-info-border;
$alert-info-text: $state-info-text;
$alert-success-bg: $state-success-bg;
$alert-success-border: $state-success-border;
$alert-success-text: $state-success-text;
$alert-warning-bg: $state-warning-bg;
$alert-warning-border: $state-warning-border;
$alert-warning-text: $state-warning-text;

// To get service status messages consistent with brand colors
$primary: $brand-primary;
$warning: $brand-warning;
$success: $brand-success;
$info: $brand-info;
$danger: $brand-danger;
$input-border-placeholder: white;

// Service Catalog panel hover highlight
$panel-list-item: lighten(desaturate(adjust-hue($panel-primary-heading-bg, -6), 20.79%), 58.04);
$panel-primary-heading-bg: #C81420;

$multiple-issues-color: #7070B3;
$no-issue-color: lighten($brand-success, 40%);
$planned-maintenance-color: lighten($brand-info, 35%);
$service-degredation-color: lighten($brand-warning, 40%);
$service-outage-color: lighten($brand-danger, 45%);

$no-issue-border-color: $brand-success;
$planned-maintenance-border-color: $brand-info;
$service-degredation-border-color: $brand-warning;
$service-outage-border-color: $brand-danger;

$no-issues-text: $state-success-text;
$planned-maintenance-text: $state-info-text;
$service-degredation-text: $state-info-text;
$service-outage-text: $state-danger-bg;

$login-btn-bg: $btn-primary-bg;
$login-btn-border: $btn-primary-border;

$qa-tag-color: $state-info-text;
$qa-tag-bg: $state-info-bg;
$qa-tag-border: $state-info-bg;
$qa-tag-hover-color: darken($qa-tag-color, 10%);
$qa-tag-hover-bg: darken($qa-tag-bg, 10%);

$qa-thread-tag-color: $state-info-text;
$qa-thread-tag-bg: $state-info-bg;
$qa-thread-tag-hover-color: darken($qa-thread-tag-color, 10%);
$qa-thread-tag-hover-bg: darken($qa-thread-tag-bg, 10%);

$qa-panel-link-color: $link-color;
$select2-container-active: $input-border-focus;

$not-webkit-outline-color: $input-border-focus;
$webkit-outline-color: $input-border-focus;

$label-success-bg: lighten(saturate($brand-success, 3.67%), 28.24);
$label-info-bg: lighten(desaturate($brand-info, 3.27%), 19.02);
$label-warning-bg: lighten(saturate(adjust-hue($brand-warning, -3), 17.70%), 29.61);
$label-danger-bg: lighten(saturate(adjust-hue($brand-danger, 354), 42.52%), 42.94);
$label-primary-bg: #B10510;
$data-table-selected: $brand-primary;

$button-selected-color: $btn-primary-bg;
$dropdown-link-active-bg: $brand-primary;
$dropdown-link-active-color: #ffffff;
$widget-editor-fa-bg: $brand-primary;

$input-border-tab-focus: $input-border-focus;

$fav-star-color: darken($brand-warning, 20%);
$fav-star-color-off: #ffffff;
$fav-star-outline-color: #6b611f;
$fav-star-outline: -1px 0 $fav-star-outline-color, 0 1px $fav-star-outline-color, 1px 0 $fav-star-outline-color, 0 -1px $fav-star-outline-color;

$sc-field-error-color: #1a424b;
$qa-star-color-on: $brand-warning;
$qa-star-color-off: #ffffff;

$list-group-link-color: $brand-primary;
$list-group-hover-bg: lighten($panel-primary-heading-bg, 40%);

$accessible-placeholder-gray: #565656;

// ── Icon colors ──
$icon-color: $brand-success;
$icon-color-hover: $brand-primary;
$icon-color-active: $brand-primary-dark;
$icon-color-muted: $gray-light;
$icon-color-inverse: #ffffff;

// ── Widget/category icon chip background ──
$widget-icon-color: $brand-success;
$widget-icon-bg: $no-issue-color;

// ── Futuristic accents: gradients + glow ──
$gradient-primary-start: $brand-primary;
$gradient-primary-end: darken($brand-primary, 15%);
$gradient-success-start: $brand-success;
$gradient-success-end: darken($brand-success, 15%);
$glow-primary: rgba(227, 6, 19, 0.45);
$glow-success: rgba(0, 122, 51, 0.45);
$glass-bg: rgba(255, 255, 255, 0.65);
$glass-border: rgba(255, 255, 255, 0.4);
/*
===============================================================================
MORWE HOLDINGS — Launchpad SPAR Theme — FUTURISTIC / BOLD edition
Paste this into the Theme's "CSS" field
(Pair with launchpad-spar-variables.scss in the "CSS Variables" field)
===============================================================================
*/

$border-radius-base: 10px;
$border-radius-large: 16px;
$border-radius-small: 6px;
$btn-border-radius-base: 999px;
$btn-border-radius-large: 999px;
$btn-border-radius-small: 999px;
$input-border-radius: 10px;
$panel-border-radius: 16px;

/*
-------------------------------------------------------------------------------
ICONS — glowing gradient chips, idle float, bounce-on-hover
-------------------------------------------------------------------------------
*/
.sp-icon,
[class*="icon-"],
.fa,
i[class^="fa-"] {
  color: $icon-color;
  transition: color 250ms cubic-bezier(0.34,1.56,0.64,1),
              transform 250ms cubic-bezier(0.34,1.56,0.64,1),
              filter 250ms ease;
}
.sp-icon:hover,
[class*="icon-"]:hover {
  color: $icon-color-hover;
  transform: translateY(-2px) scale(1.12);
  filter: drop-shadow(0 0 6px $glow-primary);
}
.navbar .sp-icon,
.navbar-inverse [class*="icon-"] {
  color: #ffffff;
}
.navbar .sp-icon:hover {
  color: $navbar-inverse-link-hover-color;
  background: rgba(255,255,255,0.15);
  border-radius: 999px;
  filter: drop-shadow(0 0 8px rgba(252, 211, 77, 0.6));
}

@keyframes iconFloat {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-3px); }
}

.icon-chip {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: linear-gradient(135deg, $gradient-success-start 0%, $gradient-success-end 100%);
  color: #ffffff;
  box-shadow: 0 4px 14px $glow-success;
  animation: iconFloat 3.2s ease-in-out infinite;
  transition: transform 300ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 300ms ease;
}
.icon-chip:hover {
  transform: scale(1.14) rotate(-4deg);
  box-shadow: 0 8px 22px $glow-success;
  animation-play-state: paused;
}
.icon-chip--accent {
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%);
  box-shadow: 0 4px 14px $glow-primary;
}
.icon-chip--accent:hover {
  box-shadow: 0 8px 22px $glow-primary;
}

/* Notification / status pulse ring */
@keyframes glowPulseRing {
  0%   { box-shadow: 0 0 0 0 $glow-primary; }
  70%  { box-shadow: 0 0 0 12px rgba(227, 6, 19, 0); }
  100% { box-shadow: 0 0 0 0 rgba(227, 6, 19, 0); }
}
.status-dot--active {
  border-radius: 50%;
  animation: glowPulseRing 1.8s infinite;
}

/*
-------------------------------------------------------------------------------
SEARCH BAR — glassmorphic pill with an animated gradient focus ring
-------------------------------------------------------------------------------
*/
.search-input-wrapper {
  position: relative;
  isolation: isolate;
}
.search-input-wrapper::before {
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 999px;
  padding: 2px;
  background: conic-gradient(from 0deg, $brand-primary, $brand-success, $brand-primary);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 300ms ease;
  animation: spinGradient 3s linear infinite;
  z-index: -1;
}
.search-input-wrapper:focus-within::before {
  opacity: 1;
}
@keyframes spinGradient {
  to { transform: rotate(360deg); }
}

.search-input,
.sp-search-input,
.typeahead-input,
input[type="search"] {
  position: relative;
  height: 48px;
  border-radius: 999px !important;
  border: 1px solid #E0E0E0;
  background: $glass-bg;
  backdrop-filter: blur(8px);
  padding-left: 48px;
  padding-right: 40px;
  transition: border-color 250ms ease, box-shadow 250ms ease, background 250ms ease;
}
.search-input:focus,
.sp-search-input:focus,
input[type="search"]:focus {
  outline: none;
  background: #ffffff;
  border-color: transparent;
  box-shadow: 0 0 0 4px rgba(227, 6, 19, 0.12), 0 6px 20px rgba(0,0,0,0.08);
}
.search-input-wrapper .search-icon {
  position: absolute;
  left: 17px;
  top: 50%;
  transform: translateY(-50%);
  color: $brand-success;
  transition: color 250ms ease, transform 250ms ease;
  pointer-events: none;
}
.search-input-wrapper input:focus ~ .search-icon {
  color: $brand-primary;
  transform: translateY(-50%) scale(1.15);
}
.search-input-wrapper .clear-btn {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: $text-muted;
  border-radius: 50%;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: color 150ms ease, background 150ms ease, transform 150ms ease;
}
.search-input-wrapper .clear-btn:hover {
  color: #ffffff;
  background: $brand-primary;
  transform: translateY(-50%) rotate(90deg);
}

/*
-------------------------------------------------------------------------------
BUTTONS — bold gradient fills with a shine sweep on hover
-------------------------------------------------------------------------------
*/
.btn {
  position: relative;
  overflow: hidden;
  border-radius: 999px;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: transform 250ms cubic-bezier(0.34,1.56,0.64,1),
              box-shadow 250ms ease,
              background-color 250ms ease;
}
.btn::after {
  content: "";
  position: absolute;
  top: 0;
  left: -60%;
  width: 40%;
  height: 100%;
  background: linear-gradient(120deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.55) 50%, rgba(255,255,255,0) 100%);
  transform: skewX(-20deg);
  transition: left 550ms ease;
}
.btn:hover::after {
  left: 130%;
}
.btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 22px rgba(227, 6, 19, 0.22);
}
.btn:active {
  transform: translateY(-1px) scale(0.97);
}
.btn-primary {
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%) !important;
  border: none !important;
}
.btn-primary:hover {
  box-shadow: 0 10px 26px $glow-primary;
}
.btn-success {
  background: linear-gradient(135deg, $gradient-success-start 0%, $gradient-success-end 100%) !important;
  border: none !important;
}
.btn-success:hover {
  box-shadow: 0 10px 26px $glow-success;
}

/*
-------------------------------------------------------------------------------
PANELS / CARDS — soft glassmorphism, bold hover lift, gradient top edge
-------------------------------------------------------------------------------
*/
.panel,
.sc-widget-card,
.widget-container {
  position: relative;
  border-radius: 16px;
  background: rgba(255,255,255,0.85);
  backdrop-filter: blur(6px);
  overflow: hidden;
  transition: box-shadow 300ms cubic-bezier(0.34,1.56,0.64,1), transform 300ms cubic-bezier(0.34,1.56,0.64,1);
}
.panel::before,
.sc-widget-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
  opacity: 0;
  transition: opacity 300ms ease;
}
.panel:hover,
.sc-widget-card:hover {
  box-shadow: 0 16px 32px rgba(26, 26, 26, 0.14);
  transform: translateY(-6px);
}
.panel:hover::before,
.sc-widget-card:hover::before {
  opacity: 1;
}

/* Fade-and-rise entrance, staggered via nth-child for a "cascade" feel */
@keyframes morweFadeInUp {
  from { opacity: 0; transform: translateY(14px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}
.sp-widget,
.panel {
  animation: morweFadeInUp 450ms cubic-bezier(0.16,1,0.3,1) both;
}
.sp-widget:nth-child(2)  { animation-delay: 60ms; }
.sp-widget:nth-child(3)  { animation-delay: 120ms; }
.sp-widget:nth-child(4)  { animation-delay: 180ms; }
.sp-widget:nth-child(5)  { animation-delay: 240ms; }

/* Dual-tone gradient loading ring */
@keyframes morweSpin {
  to { transform: rotate(360deg); }
}
.sp-loading::before {
  content: "";
  display: inline-block;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  padding: 3px;
  background: conic-gradient($brand-primary, $brand-success, $brand-primary);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: morweSpin 900ms linear infinite;
}

a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(227, 6, 19, 0.35);
  border-radius: inherit;
}

/*
===============================================================================
CATALOG ITEM CLEANUP
===============================================================================
*/
.sc-quantity-container,
.quantity-container,
[class*="quantity"],
.sc-cart-quantity,
.input-group.quantity,
label[for="quantity"],
.sc-order-quantity,
.sc-quantity-selector,
div[ng-if*="showQuantitySelector"] {
  display: none !important;
}
.sc-delivery-time,
[class*="delivery-time"],
.delivery-time,
div[ng-if*="delivery_time"],
span[id*="delivery_time"] {
  display: none !important;
}
.btn-cart,
.sc-cart-btn,
[ng-click*="addToCart"],
.add-to-cart-btn,
button[id="add_to_cart_button"],
.sc-btn-group button:first-child {
  display: none !important;
}

/*
-------------------------------------------------------------------------------
"REQUEST ACCESS" CTA — bold gradient, glow pulse on load, shine on hover
-------------------------------------------------------------------------------
*/
button[id="submit-btn"],
button.btn-primary.btn-block,
.sp-order-now,
.btn.sp-order-now,
button.sp-order-now {
  position: relative;
  overflow: hidden;
  font-size: 0 !important;
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%) !important;
  border: none !important;
  border-radius: 999px !important;
  width: 100% !important;
  padding: 14px 32px !important;
  box-shadow: 0 6px 18px $glow-primary;
  animation: buttonPulse 3s infinite;
  transition: box-shadow 0.3s ease, transform 0.3s ease;
}
button[id="submit-btn"]::after,
button.btn-primary.btn-block::after,
.sp-order-now::after,
button.sp-order-now::after {
  content: 'Request Access' !important;
  font-size: 0.95rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em;
  color: #ffffff !important;
  text-transform: uppercase;
  display: block;
}
button[id="submit-btn"]:hover,
button.btn-primary.btn-block:hover,
.sp-order-now:hover,
button.sp-order-now:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 26px $glow-primary;
  animation-play-state: paused;
}

@keyframes buttonPulse {
  0%   { box-shadow: 0 0 0 0 $glow-primary; }
  70%  { box-shadow: 0 0 0 12px rgba(227, 6, 19, 0); }
  100% { box-shadow: 0 0 0 0 rgba(227, 6, 19, 0); }
}

/*
-------------------------------------------------------------------------------
AMBIENT BACKGROUND — slow-drifting dual-tone glow orbs
-------------------------------------------------------------------------------
*/
.launchpad-bg-effect {
  position: absolute;
  top: 8%;
  right: -6%;
  width: 480px;
  height: 480px;
  background: radial-gradient(circle, $glow-success 0%, rgba(0,0,0,0) 70%);
  border-radius: 50%;
  z-index: 0;
  pointer-events: none;
  animation: morweFloat 14s ease-in-out infinite alternate;
}
.launchpad-bg-effect--accent {
  position: absolute;
  bottom: 5%;
  left: -8%;
  width: 380px;
  height: 380px;
  background: radial-gradient(circle, $glow-primary 0%, rgba(0,0,0,0) 70%);
  border-radius: 50%;
  z-index: 0;
  pointer-events: none;
  animation: morweFloat 16s ease-in-out infinite alternate-reverse;
}
@keyframes morweFloat {
  0%   { transform: translateY(0) scale(1); }
  100% { transform: translateY(-30px) scale(1.1); }
}

.launchpad-card {
  position: relative;
  z-index: 1;
  transition: transform 300ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 300ms ease;
}
.launchpad-card:hover {
  transform: translateY(-8px) scale(1.01);
  box-shadow: 0 18px 34px $glow-primary;
}

/* Animated gradient stripe heading, shifts hue slowly */
@keyframes gradientShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
.spar-stripe-heading {
  position: relative;
  padding-left: 18px;
}
.spar-stripe-heading::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, $brand-primary, $brand-success, $brand-primary);
  background-size: 100% 200%;
  animation: gradientShift 4s ease infinite;
}

/* Navbar: subtle depth + animated underline for active nav items */
.navbar-inverse {
  background: linear-gradient(180deg, $navbar-inverse-bg 0%, darken($navbar-inverse-bg, 6%) 100%);
}
.navbar-inverse .nav > li > a {
  position: relative;
  transition: color 200ms ease;
}
.navbar-inverse .nav > li > a::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 4px;
  width: 0;
  height: 2px;
  background: $navbar-inverse-link-hover-color;
  transition: width 250ms ease, left 250ms ease;
}
.navbar-inverse .nav > li > a:hover::after,
.navbar-inverse .nav > li.active > a::after {
  width: 70%;
  left: 15%;
}
h1,h2,h3,h4,h5,p{
  font-family: "Libre Baskerville", serif;
  font-optical-sizing: auto;
  font-weight: <weight>;
  font-style: normal;
}
